/// Generate a [`Fix`] to remove an unnecessary dictionary spread.
fn unnecessary_spread_fix(
    dict: &ast::ExprDict,
    prev_end: TextSize,
    locator: &Locator,
) -> Option<Fix> {
    // Find the `**` token preceding the spread.
    let doublestar = SimpleTokenizer::starts_at(prev_end, locator.contents())
        .find(|tok| matches!(tok.kind(), SimpleTokenKind::DoubleStar))?;

    // Check if the dict is wrapped in parentheses, e.g., `**({"a": 1})`.
    let has_parens = SimpleTokenizer::starts_at(doublestar.end(), locator.contents())
        .skip_trivia()
        .next()
        .is_some_and(|tok| tok.kind() == SimpleTokenKind::LParen);

    if let Some(last) = dict.iter_values().last() {
        // Ex) `**{a: 1, b: 2}`
        let mut edits = vec![];
        for tok in SimpleTokenizer::starts_at(last.end(), locator.contents()).skip_trivia() {
            match tok.kind() {
                SimpleTokenKind::Comma => {
                    edits.push(Edit::range_deletion(tok.range()));
                }
                SimpleTokenKind::RBrace => {
                    edits.push(Edit::range_deletion(tok.range()));
                    if !has_parens {
                        break;
                    }
                }
                SimpleTokenKind::RParen if has_parens => {
                    edits.push(Edit::range_deletion(tok.range()));
                    break;
                }
                _ => {}
            }
        }
        Some(Fix::safe_edits(
            // Delete the first `**{` (or `**({` if parenthesized)
            Edit::deletion(doublestar.start(), dict.start() + TextSize::from(1)),
            // Delete the trailing `}` (and `)` if parenthesized)
            edits,
        ))
    } else {
        // Ex) `**{}` or `**({})`
        let end = if has_parens {
            SimpleTokenizer::starts_at(dict.end(), locator.contents())
                .skip_trivia()
                .find(|tok| tok.kind() == SimpleTokenKind::RParen)
                .map_or(dict.end(), |tok| tok.end())
        } else {
            dict.end()
        };
        Some(Fix::safe_edit(Edit::deletion(
            doublestar.start(),
            end,
        )))
    }
}

