            range.start,
            caps,
            dst,
            |caps, dst| {
                let m = caps.get(0).unwrap();
                if m.start >= range_end {
                    return false;
                }
                last_match_end = m.end;
                let start = dst.len();
                caps.interpolate(
                    |name| matcher.capture_index(name),
                    subject,
                    replacement,
                    dst,
                );
                let end = dst.len();
                matches.push(Match::new(start, end));
                true
            },
