if let Some(MappingTarget::MapToUnknown) = syntax_match {
    return Err(Error::UndetectedSyntax(path.to_string_lossy().into()));
}

if let Some(MappingTarget::MapTo(syntax_name)) = syntax_match {
    return self
        .find_syntax_by_name(syntax_name)?
        .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()));
}

// If no syntax mapping matched the full path, try again with ignored
// suffixes stripped so that --map-syntax and --ignored-suffix work together.
if syntax_match.is_none() {
    if let Some(file_name) = path.file_name().and_then(|f| f.to_str()) {
        if let Some(stripped_file_name) =
            mapping.ignored_suffixes.strip_suffix(file_name)
        {
            let stripped_path = path.with_file_name(stripped_file_name);
            let stripped_syntax_match = mapping.get_syntax_for(&stripped_path);
            if let Some(MappingTarget::MapToUnknown) = stripped_syntax_match {
                return Err(Error::UndetectedSyntax(path.to_string_lossy().into()));
            }
            if let Some(MappingTarget::MapTo(syntax_name)) = stripped_syntax_match {
                return self
                    .find_syntax_by_name(syntax_name)?
                    .ok_or_else(|| Error::UnknownSyntax(syntax_name.to_owned()));
            }
        }
    }
}

