pub(crate) fn is_empty(&self, tx: &Tx<T>) -> bool {
    let block = unsafe { self.head.as_ref() };
    // Only check has_value if the current head block actually contains self.index.
    // When self.index is at a block boundary (e.g. 32, 64, ...), the head pointer
    // may still reference the previous block. In that case, offset(self.index) wraps
    // to 0, which would incorrectly test the stale ready bit of slot 0 in the old block.
    if block.is_at_index(block::start_index(self.index)) && block.has_value(self.index) {
        return false;
    }

    // It is possible that a block has no value "now" but the list is still not empty.
    // To be sure, it is necessary to check the length of the list.
    self.len(tx) == 0
}

