async fn write_all_buf_vectored() {
    struct Wr {
        buf: BytesMut,
        cnt: usize,
    }

    impl AsyncWrite for Wr {
        fn poll_write(
            self: Pin<&mut Self>,
            _cx: &mut Context<'_>,
            _buf: &[u8],
        ) -> Poll<io::Result<usize>> {
            unreachable!("should use vectored write");
        }

        fn poll_flush(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<io::Result<()>> {
            Ok(()).into()
        }

        fn poll_shutdown(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<io::Result<()>> {
            Ok(()).into()
        }

        fn is_write_vectored(&self) -> bool {
            true
        }

        fn poll_write_vectored(
            mut self: Pin<&mut Self>,
            _cx: &mut Context<'_>,
            bufs: &[IoSlice<'_>],
        ) -> Poll<io::Result<usize>> {
            let n: usize = bufs.iter().map(|b| cmp::min(4, b.len())).sum();

            for buf in bufs {
                let n = cmp::min(4, buf.len());
                self.buf.extend(&buf[..n]);
            }

            self.cnt += 1;
            Ok(n).into()
        }
    }

    let mut wr = Wr {
        buf: BytesMut::with_capacity(64),
        cnt: 0,
    };

    let mut buf = Bytes::from_static(b"hello").chain(Bytes::from_static(b"world"));

    assert_ok!(wr.write_all_buf(&mut buf).await);
    assert_eq!(wr.buf, b"helloworld"[..]);
    // vectored write should write both chunks at once, consuming up to 4 bytes per chunk
    // first call: [hell] + [worl] = 8 bytes, second call: [o] + [d] = 2 bytes
    assert_eq!(wr.cnt, 2);
    assert!(!buf.has_remaining());
}

