#[cfg(unix)]
fn apply_ignore_signals(matches: &clap::ArgMatches) -> UResult<()> {
    if let Some(signals) = matches.get_many::<String>("ignore-signal") {
        for signal_str in signals {
            let signal_str = signal_str.as_str();
            if signal_str.is_empty() {
                // empty string means ignore default signal (PIPE)
                let signal = Signal::try_from(libc::SIGPIPE).unwrap();
                let _ = unsafe {
                    sigaction(
                        signal,
                        &SigAction::new(SigHandler::SigIgn, SaFlags::empty(), SigSet::empty()),
                    )
                };
                continue;
            }

            if let Some(sig_value) = parse_signal_value(signal_str) {
                if sig_value == 0 {
                    // Signal 0 is not a real signal, skip
                    continue;
                }
                match Signal::try_from(sig_value as i32) {
                    Ok(signal) => {
                        // SIGKILL and SIGSTOP cannot be ignored
                        if signal == Signal::SIGKILL || signal == Signal::SIGSTOP {
                            show_warning!(
                                "failed to set signal action for signal {} to ignore: Invalid argument",
                                signal_str
                            );
                            continue;
                        }
                        let _ = unsafe {
                            sigaction(
                                signal,
                                &SigAction::new(
                                    SigHandler::SigIgn,
                                    SaFlags::empty(),
                                    SigSet::empty(),
                                ),
                            )
                        };
                    }
                    Err(_) => {
                        return Err(USimpleError::new(
                            125,
                            format!("{}: invalid signal", signal_str.quote()),
                        ));
                    }
                }
            } else {
                return Err(USimpleError::new(
                    125,
                    format!("{}: invalid signal", signal_str.quote()),
                ));
            }
        }
    }
    Ok(())
}

