pub fn mkdir(path: &Path, recursive: bool, mode: u32, verbose: bool) -> UResult<()> {
    // Special case to match GNU's behavior:
    // mkdir -p foo/. should work and just create foo/
    // std::fs::create_dir("foo/."); fails in pure Rust
    let path_buf = dir_strip_dot_for_creation(path);
    let path = path_buf.as_path();

    // When using -p, if the directory already exists, don't try to chmod it.
    // GNU mkdir skips permission changes for already-existing directories.
    let path_already_exists = path.is_dir();

    create_dir(path, recursive, verbose, false)?;

    if recursive && path_already_exists {
        Ok(())
    } else {
        chmod(path, mode)
    }
}

