#[cfg(not(windows))]
#[test]
fn test_mkdir_parent_mode_skip_existing_last_component_chmod() {
    let (at, mut ucmd) = at_and_ucmd!();

    at.mkdir("a");
    let original_perms = at.metadata("a").permissions().mode();

    // chmod the directory to something different, then verify mkdir -p doesn't change it
    std::fs::set_permissions(at.plus("a"), std::fs::Permissions::from_mode(0o700)).unwrap();

    ucmd.arg("-p").arg("a").succeeds().no_stderr().no_stdout();

    // mkdir -p should not modify permissions of an existing directory
    assert_eq!(at.metadata("a").permissions().mode() as mode_t, 0o40700);

    // Verify permissions were NOT changed back to the original
    // This confirms mkdir -p skipped the chmod
    assert!(at.dir_exists("a"));
}

